			const email = 'pendingonly@example.com';
			let recipient;
			plugins.hooks.register('pending-only-email-test', {
				hook: 'filter:email.send',
				method: async (data) => { recipient = data.to; return data; },
			});
			try {
				const code = await User.email.sendValidationEmail(uid, { email });
				const confirmation = await db.getObject(`confirm:${code}`);
				assert.strictEqual(await db.get(`confirm:byUid:${uid}`), code);
				assert.strictEqual(confirmation.email, email);
				assert.strictEqual(Number(confirmation.uid), uid);
				assert(Number(confirmation.expires) > Date.now());
				assert.strictEqual(await User.email.getEmailForValidation(uid), email);
				assert.strictEqual(await User.email.isValidationPending(uid), true);
				assert.strictEqual(await User.email.isValidationPending(uid, email.toUpperCase()), true);
				assert.strictEqual(await User.email.isValidationPending(uid, 'different@example.com'), false);
				assert.strictEqual(recipient, email);

				await assert.rejects(
					User.email.sendValidationEmail(uid),
					/confirm-email-already-sent/
				);
				const replacement = await User.email.sendValidationEmail(uid, { force: true });
				assert.notStrictEqual(replacement, code);
				assert.strictEqual(await db.getObject(`confirm:${code}`), null);
				assert.strictEqual(await db.get(`confirm:byUid:${uid}`), replacement);
				assert.strictEqual(recipient, email);
				await User.email.expireValidation(uid);
				assert.strictEqual(await db.get(`confirm:byUid:${uid}`), null);
				assert.strictEqual(await db.getObject(`confirm:${replacement}`), null);
